const binaryData = $input.item.binary;
const outputItems = [];

for (const key in binaryData) {
    if (binaryData.hasOwnProperty(key)) {
        const file = binaryData[key];
        const fileName = file.fileName;
        let fileExtension = '';
        let fileBaseName = fileName;

        // 取副檔名
        const lastDotIndex = fileName.lastIndexOf('.');
        if (lastDotIndex !== -1 && lastDotIndex < fileName.length - 1) {
            fileExtension = fileName.substring(lastDotIndex + 1).toLowerCase();
            fileBaseName = fileName.substring(0, lastDotIndex);
        }

        // 將結果添加到輸出
        outputItems.push({
            json: {
                originalFileName: fileName,
                fileBaseName: fileBaseName,
                fileExtension: fileExtension,
            },
            binary: { [key]: file }
        });
    }
}

return outputItems;

const rawText = $input.first().json.content.parts[0].text ?? '';

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = null;
}

// 模型沒回合法 JSON 時，至少把原始輸出當純文字送下去，維持舊行為
if (!parsed || typeof parsed !== 'object') {
  return [
    {
      json: {
        text: rawText,
        content_type: 'plain_text',
        handwritten: false,
        estimated: false,
        table: null,
        chart: null,
        languages: [],
        primary_language: 'unknown',
      },
    },
  ];
}

const ESTIMATED_NOTICE = '（數值為推估，僅供參考）';
const UNREADABLE = '〔難以辨識〕';

let text = typeof parsed.text === 'string' ? parsed.text.trim() : '';

// 電視新聞畫面：text 一律由 tv_news 欄位重建，不採用模型自己寫的 text。
// 受訪者字幕與跑馬燈就算被模型寫進 text 也送不到下游——字幕被當成查核主張
// 送出去，是 CARE/scripts/tv_news_eval.py 量到的主要失效。
// 沒有標題時仍要給一句話：text 為空會在 media_handler 被當成「無法辨識」擋掉。
const TV_CHANNELS = ['台視', '中視', '華視', '民視', '公視', 'TVBS', '三立', '東森', '中天', '年代', '壹電視', '非凡', '寰宇'];
if (parsed.content_type === 'tv_news' && parsed.tv_news && typeof parsed.tv_news === 'object') {
  const tv = parsed.tv_news;
  const headline = typeof tv.headline === 'string' ? tv.headline.trim() : '';
  const lines = ['【電視新聞畫面】'];
  // 「不確定」或清單外的值都不寫，避免把猜的台名當事實傳下去
  if (TV_CHANNELS.includes(tv.channel)) lines.push(`電視台：${tv.channel}`);
  if (headline) {
    lines.push(`新聞標題：${headline}`);
    if (tv.headline_complete === false) lines.push('（標題可能不完整或有字看不清楚）');
  } else {
    lines.push('畫面上沒有看到這則新聞的標題');
  }
  text = lines.join('\n');
}

// Respond to Webhook 只回傳 $json.text，後端 _extract_user_text_via_webhook 也只取
// 單一字串欄位。所以模型若漏填 text，就從結構化欄位重建，否則下游會收到空字串並
// 在 media_handler 被當成「無法辨識」擋掉。
if (!text && parsed.table && Array.isArray(parsed.table.columns)) {
  const cols = parsed.table.columns.map((c) => String(c ?? ''));
  const rows = Array.isArray(parsed.table.rows) ? parsed.table.rows : [];
  const toRow = (cells) =>
    '| ' + cells.map((c) => String(c ?? '')).join(' | ') + ' |';
  text = [
    toRow(cols),
    '| ' + cols.map(() => '---').join(' | ') + ' |',
    ...rows.map((r) => toRow(Array.isArray(r) ? r : [r])),
  ].join('\n');
}

if (!text && parsed.chart) {
  const chart = parsed.chart;
  const xLabels = Array.isArray(chart.x_labels) ? chart.x_labels : [];
  const series = Array.isArray(chart.series) ? chart.series : [];
  const lines = [
    `圖表類型：${chart.chart_type ?? 'other'}，X 軸：${chart.x_label || '未標示'}，Y 軸：${chart.y_label || '未標示'}`,
  ];
  for (const s of series) {
    const points = Array.isArray(s.points) ? s.points : [];
    const rendered = points
      .map((p, i) => `${xLabels[i] ?? i + 1}=${p === null || p === undefined ? UNREADABLE : p}`)
      .join('、');
    lines.push(`${s.name || '數列'}：${rendered}`);
  }
  text = lines.join('\n');
}

// 推估註記必須出現在 text 裡，因為 estimated 旗標本身傳不到後端
if (text && parsed.estimated === true && !text.startsWith(ESTIMATED_NOTICE)) {
  text = `${ESTIMATED_NOTICE}\n${text}`;
}

return [
  {
    json: {
      text,
      content_type: parsed.content_type ?? 'plain_text',
      handwritten: parsed.handwritten ?? false,
      estimated: parsed.estimated ?? false,
      table: parsed.table ?? null,
      chart: parsed.chart ?? null,
      tv_news: parsed.tv_news ?? null,
      languages: parsed.languages ?? [],
      primary_language: parsed.primary_language ?? parsed.language ?? 'unknown',
    },
  },
];
